using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Enums;
namespace Namaa.Application.Quotations.Commands.UpdateQuotation;
public sealed class UpdateQuotationCommandHandler(IQuotationRepository repository,IApplicationDbContext db):IRequestHandler<UpdateQuotationCommand,Result<QuotationDto>>{public async Task<Result<QuotationDto>>Handle(UpdateQuotationCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<QuotationDto>(QuotationErrors.NotFound);if(e.Status!=QuotationStatus.Draft)return Result.Failure<QuotationDto>(QuotationErrors.NotDraft);e.UpdateDetails(request.Title,request.IssueDate,request.ValidUntil,request.Notes,request.Terms);await db.SaveChangesAsync(cancellationToken);return Result.Success(QuotationDto.FromEntity(e));}}

